// 从时效记录推导状态
export function getLeadtimeStatus(r: LeadTimeRecord): OrderStatus {
  if (r.status) return r.status;
  if (r.arrivalQuality && r.arrivalQuality !== 'normal') return 'abnormal';
  if (r.arrivedAt) {
    return r.arrivalQuality === 'normal' ? 'warehoused' : 'arrived';
  }
  if (r.trackingNumber) {
    const days = calcLeadDays(r.orderedAt, new Date().toISOString().slice(0, 10));
    if (days !== null && days > 3) return 'in_transit';
    return 'shipped';
  }
  return 'pending_ship';
}

// ========== 统计 ==========
export function computeStats(orders: PurchaseOrder[]) {
  const stats = {
    total: orders.length,
    inTransit: 0,
    arrived: 0,
    warehoused: 0,
    abnormal: 0,
    ordered: 0,
    pendingShip: 0,
    shipped: 0,
  };
  orders.forEach((o) => {
    if (o.status === 'in_transit') stats.inTransit++;
    if (o.status === 'arrived') stats.arrived++;
    if (o.status === 'warehoused') stats.warehoused++;
    if (o.status === 'abnormal') stats.abnormal++;
    if (o.status === 'ordered') stats.ordered++;
    if (o.status === 'pending_ship') stats.pendingShip++;
    if (o.status === 'shipped') stats.shipped++;
  });
  return stats;
}

// 本月采购总金额（按 createdAt / purchaseDate 归属自然月）
export function computeMonthlyAmount(orders: PurchaseOrder[]): number {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth();
  let total = 0;
  orders.forEach((o) => {
    if (!o.amount) return;
    const dateStr = o.purchaseDate || o.purchaseTime || o.createdAt;
    if (!dateStr) return;
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return;
    if (d.getFullYear() === y && d.getMonth() === m) {
      total += o.amount;
    }
  });
  return Math.round(total * 100) / 100;
}

// ========== 运输天数计算 ==========
function getShippingDays(order: PurchaseOrder): number | null {
  const baseTime = order.shippedAt || order.updatedAt || order.createdAt;
  if (!baseTime) return null;
  const start = new Date(baseTime).getTime();
  const now = Date.now();
  const diffDays = (now - start) / (1000 * 60 * 60 * 24);
  return Math.floor(diffDays);
}

function extractExpectedDays(text: string): number | null {
  const match = text.match(/(\d+)\s*天/);
  if (match) return parseInt(match[1], 10);
  const rangeMatch = text.match(/(\d+)\s*[-~～]\s*(\d+)\s*天/);
  if (rangeMatch) return parseInt(rangeMatch[2], 10);
  return null;
}

// ========== 异常检测（采购单） ==========
export function detectAbnormalRecords(orders: PurchaseOrder[]): AbnormalRecord[] {
  const results: AbnormalRecord[] = [];

  orders.forEach((order) => {
    if (order.status === 'shipped' || order.status === 'in_transit') {
      const days = getShippingDays(order);
      const expectedDays = order.expressTimeline ? extractExpectedDays(order.expressTimeline) : null;
      const isOverdue = (days !== null && days > 7) || (expectedDays !== null && expectedDays > 7);
      if (isOverdue) {
        const info = days !== null ? `已运输 ${days} 天` : `预计时效 ${expectedDays} 天`;
        results.push({
          type: 'shipping_delay',
          order,
          triggerInfo: info,
          suggestion: ABNORMAL_SUGGESTIONS.shipping_delay,
        });
      }
    }

    const arrivedOrWarehoused = (s: OrderStatus) => s === 'arrived' || s === 'warehoused';

    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'damaged') {
      results.push({
        type: 'arrival_damaged',
        order,
        triggerInfo: '到货质检：破损',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_damaged,
      });
    }
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'defective') {
      results.push({
        type: 'arrival_defective',
        order,
        triggerInfo: '到货质检：瑕疵',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_defective,
      });
    }
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'missing') {
      results.push({
        type: 'quantity_missing',
        order,
        triggerInfo: '到货质检：漏件',
        suggestion: ABNORMAL_SUGGESTIONS.quantity_missing,
      });
    }
  });

  return results;
}

export function computeAbnormalStats(records: AbnormalRecord[]) {
  return {
    total: records.length,
    shippingDelay: records.filter((r) => r.type === 'shipping_delay').length,
    damaged: records.filter((r) => r.type === 'arrival_damaged').length,
    defective: records.filter((r) => r.type === 'arrival_defective').length,
    missing: records.filter((r) => r.type === 'quantity_missing').length,
  };
}

// ========== 异常检测（时效记录） ==========
export function detectLeadTimeAbnormalRecords(records: LeadTimeRecord[]): LeadTimeAbnormalRecord[] {
  const results: LeadTimeAbnormalRecord[] = [];

  records.forEach((record) => {
    const leadDays = calcLeadDays(record.orderedAt, record.arrivedAt);

    if (leadDays !== null && leadDays > 7) {
      results.push({
        type: 'shipping_delay',
        record,
        triggerInfo: `实际时效 ${leadDays} 天`,
        suggestion: ABNORMAL_SUGGESTIONS.shipping_delay,
      });
    } else if (!record.arrivedAt && record.orderedAt) {
      const t = new Date(record.orderedAt).getTime();
      if (isNaN(t)) return;
      const daysSinceOrder = Math.floor((Date.now() - t) / (1000 * 60 * 60 * 24));
      if (daysSinceOrder > 7) {
        results.push({
          type: 'shipping_delay',
          record,
          triggerInfo: `已下单 ${daysSinceOrder} 天未到货`,
          suggestion: ABNORMAL_SUGGESTIONS.shipping_delay,
        });
      }
    }

    const arrived = !!record.arrivedAt;
    if (arrived && record.arrivalQuality === 'damaged') {
      results.push({
        type: 'arrival_damaged',
        record,
        triggerInfo: '到货质检：破损',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_damaged,
      });
    }
    if (arrived && record.arrivalQuality === 'defective') {
      results.push({
        type: 'arrival_defective',
        record,
        triggerInfo: '到货质检：瑕疵',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_defective,
      });
    }
    if (arrived && record.arrivalQuality === 'missing') {
      results.push({
        type: 'quantity_missing',
        record,
        triggerInfo: '到货质检：漏件',
        suggestion: ABNORMAL_SUGGESTIONS.quantity_missing,
      });
    }
  });

  return results;
}

export function computeLeadTimeAbnormalStats(records: LeadTimeAbnormalRecord[]) {
  return {
    total: records.length,
    shippingDelay: records.filter((r) => r.type === 'shipping_delay').length,
    damaged: records.filter((r) => r.type === 'arrival_damaged').length,
    defective: records.filter((r) => r.type === 'arrival_defective').length,
    missing: records.filter((r) => r.type === 'quantity_missing').length,
  };
}

 // 避免 ABNORMAL_TYPE_META 未使用告警
 void ABNORMAL_TYPE_META;

 // ========== 跨境订单存取 ==========
 export function loadCrossBorderOrders(): CrossBorderOrder[] {
   try {
     const raw = scopedStorage.getItem(STORAGE_KEY_CROSSBORDER);
     if (raw) {
       const data = JSON.parse(raw) as CrossBorderOrder[];
       if (Array.isArray(data)) return data;
     }
   } catch {
     /* ignore */
   }
   return [];
 }

 export function saveCrossBorderOrders(orders: CrossBorderOrder[]) {
   try {
     scopedStorage.setItem(STORAGE_KEY_CROSSBORDER, JSON.stringify(orders));
   } catch {
     /* ignore */
   }
 }

 // ========== 跨境订单预警分级 ==========
 // 运输超20天=注意(黄) / 25天=警告(橙) / 30天=严重(红) / 35天=异常(深红)
 export function getCrossBorderAlert(order: CrossBorderOrder): CrossBorderAlert | null {
   // 已到货/已入仓 → 无预警
   if (order.status === 'arrived' || order.status === 'warehoused' || order.arrivedAt) {
     return null;
   }
   // 取基准时间：已发货用 shippedAt，否则用 orderedAt
   const baseTime = order.shippedAt || order.orderedAt;
   if (!baseTime) return null;
   const t = new Date(baseTime).getTime();
   if (isNaN(t)) return null;
   const days = Math.floor((Date.now() - t) / (1000 * 60 * 60 * 24));

   if (days >= 35) {
     return {
       level: 'critical',
       label: '严重异常',
       color: 'bg-red-700',
       textColor: 'text-red-700',
       message: `超${days}天，严重运输异常，疑似丢件，请立即处理`,
       days,
     };
   }
   if (days >= 30) {
     return {
       level: 'severe',
       label: '严重',
       color: 'bg-red-500',
       textColor: 'text-red-600',
       message: `超${days}天，请货代尽快处理，防止丢件`,
       days,
     };
   }
   if (days >= 25) {
     return {
       level: 'warning',
       label: '警告',
       color: 'bg-orange-500',
       textColor: 'text-orange-600',
       message: `超${days}天，请联系货代并催促尾端派送`,
       days,
     };
   }
   if (days >= 20) {
     return {
       level: 'attention',
       label: '注意',
       color: 'bg-amber-500',
       textColor: 'text-amber-600',
       message: `运输已达${days}天，请关注`,
       days,
     };
   }
   return null;
 }

 // 跨境订单统计
 export function calcCrossBorderStats(orders: CrossBorderOrder[]) {
   const stats = {
     total: orders.length,
     inTransit: 0,
     arrived: 0,
     warehoused: 0,
     abnormal: 0,
     attention: 0,
     warning: 0,
     severe: 0,
     critical: 0,
   };
   orders.forEach((o) => {
     if (o.status === 'in_transit' || o.status === 'shipped') stats.inTransit++;
     if (o.status === 'arrived') stats.arrived++;
     if (o.status === 'warehoused') stats.warehoused++;
     const alert = getCrossBorderAlert(o);
     if (alert) {
       if (alert.level === 'attention') stats.attention++;
       if (alert.level === 'warning') stats.warning++;
       if (alert.level === 'severe') stats.severe++;
       if (alert.level === 'critical') stats.critical++;
       if (alert.level === 'severe' || alert.level === 'critical') stats.abnormal++;
     }
     if (o.status === 'abnormal') stats.abnormal++;
   });
   return stats;
 }
